{
  "packet_id": "H6-T04-1",
  "claim_id": "C027",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C027.component",
    "value": "Reproducible differences under common conditions would support distinguishable onboarding behaviors.",
    "scope": "Conditional support for behavioral distinctions, not an assertion that differences have been observed or causes identified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P018 supplies the conditional behavioral inference and its reproducibility and common-condition requirements. P027 supplies the boundary against identifying causes from behavioral retention alone."
    }
  },
  "signal_basis": {
    "component_id": "C027.signal_basis",
    "value": "Reproducible concentrations of trajectories differ in milestone position, waiting duration, returns to active work or time to first publication under common onboarding and observation conditions.",
    "scope": "Prospective cohort comparisons using the same onboarding pathway and comparable observation windows, accounting for conditions that can shift apparent retention.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P026",
          "role": "SUPPORT"
        },
        {
          "source_id": "P001",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the trajectory measurements, reproducibility requirement, common pathway and observation conditions, and qualifications concerning factors that shift retention. P001 identifies the prospective cohort."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C027.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No additional unresolved empirical relation is needed for this bounded descriptive inference."
    }
  },
  "rationale": "Reproducible differences in measured onboarding trajectories under comparable conditions support distinguishing observed behaviors. The claim does not require those differences to establish fixed customer segments or identify underlying causes.",
  "uncertainty": "The signal leaves causal explanations unresolved, but that uncertainty does not defeat the claimed behavioral distinction.",
  "anomalies": []
}
